-- Expert cards: sales text vs evidence (2026-11-27).
-- card.evidence = how each number was collected (basis, listings, confidence, source notes): website only.
-- project_experts_public (Sara, MCP, voice assistant): card without evidence and without sources.
-- project_experts_web (site build, «أسئلة بالأرقام»): card with evidence, without sources.

create or replace view public.project_experts_public as
  select e.project_id, e.slug, e.card_version, e.card - 'sources' - 'evidence' as card, e.updated_at
  from public.project_experts e
  where e.status = 'active';
grant select on public.project_experts_public to anon, authenticated;

create or replace view public.project_experts_web as
  select e.project_id, e.slug, e.card_version, e.card - 'sources' as card, e.updated_at
  from public.project_experts e
  where e.status = 'active';
grant select on public.project_experts_web to anon, authenticated;

